create table if not exists public.fediverse_instance_discovery_runs (id uuid primary key default gen_random_uuid(),request_id bigint unique,requested_at timestamptz not null default now(),processed_at timestamptz,discovered_count integer not null default 0,status text not null default 'pending' check (status in ('pending','processed','failed')),error text);
alter table public.fediverse_instance_discovery_runs enable row level security;
revoke all on public.fediverse_instance_discovery_runs from anon, authenticated;
create or replace function public.request_fediverse_instance_discovery() returns bigint language plpgsql security definer set search_path=public as $$ declare v_request_id bigint; begin select net.http_post(url:='https://api.fediverse.observer/',headers:=jsonb_build_object('Content-Type','application/json','Accept','application/json'),body:=jsonb_build_object('query','query TestagramDiscovery { nodes { domain name softwarename status } }','operationName','TestagramDiscovery'),timeout_milliseconds:=30000) into v_request_id; insert into public.fediverse_instance_discovery_runs(request_id) values(v_request_id); return v_request_id; end; $$;
create or replace function public.process_fediverse_instance_discovery() returns integer language plpgsql security definer set search_path=public as $$ declare r record; v_json jsonb; v_count integer:=0; v_domain text; v_software text; begin for r in select d.id,d.request_id,h.status_code,h.content,h.error_msg,h.timed_out from public.fediverse_instance_discovery_runs d join net._http_response h on h.id=d.request_id where d.status='pending' order by d.requested_at limit 5 loop if r.status_code between 200 and 299 and not coalesce(r.timed_out,false) and r.content is not null then begin v_json:=r.content::jsonb; for v_domain,v_software in select lower(btrim(coalesce(x.value->>'domain',''))),lower(btrim(coalesce(x.value->>'softwarename','unknown'))) from jsonb_array_elements(coalesce(v_json->'data'->'nodes','[]'::jsonb)) x(value) loop if v_domain~'^[a-z0-9][a-z0-9.-]*[a-z0-9]$' and v_domain not like '%.local' and v_domain not like 'localhost%' and length(v_domain)<=253 then insert into public.federated_instances(domain,base_url,provider,software,public_timeline_available,discovered_at,updated_at,next_sync_at) values(v_domain,'https://'||v_domain,'fediverse-observer',nullif(v_software,''),false,now(),now(),now()) on conflict(domain) do update set base_url=excluded.base_url,provider=excluded.provider,software=coalesce(excluded.software,federated_instances.software),discovered_at=coalesce(federated_instances.discovered_at,excluded.discovered_at),updated_at=now(),next_sync_at=least(coalesce(federated_instances.next_sync_at,excluded.next_sync_at),excluded.next_sync_at); v_count:=v_count+1; end if; end loop; update public.fediverse_instance_discovery_runs set status='processed',processed_at=now(),discovered_count=v_count where id=r.id; exception when others then update public.fediverse_instance_discovery_runs set status='failed',processed_at=now(),error=left(sqlerrm,2000) where id=r.id; end; else update public.fediverse_instance_discovery_runs set status='failed',processed_at=now(),error=left(coalesce(r.error_msg,'HTTP '||coalesce(r.status_code::text,'unknown')),2000) where id=r.id; end if; end loop; return v_count; end; $$;
revoke all on function public.request_fediverse_instance_discovery() from public,anon,authenticated;
revoke all on function public.process_fediverse_instance_discovery() from public,anon,authenticated;
grant execute on function public.request_fediverse_instance_discovery() to postgres;
grant execute on function public.process_fediverse_instance_discovery() to postgres;
select cron.unschedule(jobid) from cron.job where jobname in ('testagram-fediverse-instance-discovery','testagram-fediverse-instance-discovery-process');
select cron.schedule('testagram-fediverse-instance-discovery','17 2 * * *',$$select public.request_fediverse_instance_discovery();$$);
select cron.schedule('testagram-fediverse-instance-discovery-process','*/5 * * * *',$$select public.process_fediverse_instance_discovery();$$);